 static class DB extends SQLiteOpenHelper{DB(Context c){super(c,"smartcompany2.db",null,11);}public void onCreate(SQLiteDatabase d){schema(d);}public void onUpgrade(SQLiteDatabase d,int o,int n){schema(d);}void schema(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE,qty REAL NOT NULL DEFAULT 0,sale_price REAL NOT NULL DEFAULT 0,cost REAL NOT NULL DEFAULT 0,reorder REAL NOT NULL DEFAULT 0)");try{d.execSQL("ALTER TABLE products ADD COLUMN barcode TEXT");}catch(Exception ignored){}d.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS idx_products_barcode ON products(barcode) WHERE barcode IS NOT NULL AND barcode != ''");d.execSQL("CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,credit_limit REAL NOT NULL DEFAULT 0)");try{d.execSQL("ALTER TABLE customers ADD COLUMN credit_limit REAL NOT NULL DEFAULT 0");}catch(Exception ignored){}d.execSQL("CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT)");d.execSQL("CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,job_title TEXT NOT NULL DEFAULT '',salary REAL NOT NULL DEFAULT 0)");try{d.execSQL("ALTER TABLE employees ADD COLUMN job_title TEXT NOT NULL DEFAULT ''");}catch(Exception ignored){}try{d.execSQL("ALTER TABLE employees ADD COLUMN salary REAL NOT NULL DEFAULT 0");}catch(Exception ignored){}d.execSQL("CREATE TABLE IF NOT EXISTS payroll_events(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER NOT NULL,kind TEXT NOT NULL,amount REAL NOT NULL,note TEXT,period_month TEXT NOT NULL,created_at INTEGER)");d.execSQL("CREATE INDEX IF NOT EXISTS idx_payroll_employee_month ON payroll_events(employee_id,period_month)");d.execSQL("CREATE TABLE IF NOT EXISTS payroll_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,period_month TEXT NOT NULL UNIQUE,journal_entry_id INTEGER NOT NULL,gross_total REAL NOT NULL,advances_total REAL NOT NULL,deductions_total REAL NOT NULL,net_total REAL NOT NULL,created_at INTEGER NOT NULL)");d.execSQL("CREATE TABLE IF NOT EXISTS payroll_run_lines(id INTEGER PRIMARY KEY AUTOINCREMENT,payroll_run_id INTEGER NOT NULL,employee_id INTEGER NOT NULL,salary REAL NOT NULL,advances REAL NOT NULL,deductions REAL NOT NULL,net_payable REAL NOT NULL,paid_amount REAL NOT NULL DEFAULT 0,UNIQUE(payroll_run_id,employee_id))");d.execSQL("CREATE TABLE IF NOT EXISTS payroll_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,payroll_run_line_id INTEGER NOT NULL,amount REAL NOT NULL,journal_entry_id INTEGER NOT NULL,created_at INTEGER NOT NULL,note TEXT)");try{d.execSQL("ALTER TABLE payroll_events ADD COLUMN posted INTEGER NOT NULL DEFAULT 0");}catch(Exception ignored){}d.execSQL("CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,party TEXT,total REAL NOT NULL,paid REAL NOT NULL DEFAULT 0,remaining REAL NOT NULL DEFAULT 0,created_at INTEGER)");try{d.execSQL("ALTER TABLE transactions ADD COLUMN original_transaction_id INTEGER");}catch(Exception ignored){}d.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS idx_transaction_single_return ON transactions(original_transaction_id) WHERE original_transaction_id IS NOT NULL");try{d.execSQL("ALTER TABLE transactions ADD COLUMN invoice_no TEXT");}catch(Exception ignored){}try{d.execSQL("ALTER TABLE transactions ADD COLUMN customer_id INTEGER");}catch(Exception ignored){}try{d.execSQL("ALTER TABLE transactions ADD COLUMN supplier_id INTEGER");}catch(Exception ignored){}d.execSQL("INSERT INTO customers(name) SELECT DISTINCT t.party FROM transactions t WHERE t.type='SALE' AND t.party IS NOT NULL AND TRIM(t.party)!='' AND NOT EXISTS(SELECT 1 FROM customers c WHERE c.name=t.party)");d.execSQL("INSERT INTO suppliers(name) SELECT DISTINCT t.party FROM transactions t WHERE t.type='PURCHASE' AND t.party IS NOT NULL AND TRIM(t.party)!='' AND NOT EXISTS(SELECT 1 FROM suppliers s WHERE s.name=t.party)");d.execSQL("UPDATE transactions SET customer_id=(SELECT MIN(c.id) FROM customers c WHERE c.name=transactions.party) WHERE type='SALE' AND customer_id IS NULL");d.execSQL("UPDATE transactions SET supplier_id=(SELECT MIN(s.id) FROM suppliers s WHERE s.name=transactions.party) WHERE type='PURCHASE' AND supplier_id IS NULL");d.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS idx_transactions_invoice_no ON transactions(invoice_no) WHERE invoice_no IS NOT NULL AND invoice_no != ''");d.execSQL("CREATE TABLE IF NOT EXISTS invoice_items(id INTEGER PRIMARY KEY AUTOINCREMENT,transaction_id INTEGER,product_id INTEGER,qty REAL,price REAL,cost REAL,discount REAL NOT NULL DEFAULT 0)");
 d.execSQL("CREATE TABLE IF NOT EXISTS bank_accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,bank_name TEXT NOT NULL,account_name TEXT NOT NULL UNIQUE,opening_balance REAL NOT NULL DEFAULT 0)");
 d.execSQL("CREATE TABLE IF NOT EXISTS bank_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL,kind TEXT NOT NULL,amount REAL NOT NULL,note TEXT,created_at INTEGER)");
 d.execSQL("CREATE TABLE IF NOT EXISTS checks(id INTEGER PRIMARY KEY AUTOINCREMENT,direction TEXT NOT NULL,check_no TEXT NOT NULL,bank_name TEXT,party TEXT,amount REAL NOT NULL,issue_date TEXT,due_date TEXT NOT NULL,status TEXT NOT NULL,created_at INTEGER,UNIQUE(direction,check_no))");
 d.execSQL("CREATE INDEX IF NOT EXISTS idx_checks_due_status ON checks(due_date,status)");
 d.execSQL("CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,name TEXT NOT NULL,type TEXT)");
 d.execSQL("CREATE TABLE IF NOT EXISTS journal_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,transaction_id INTEGER,created_at INTEGER,description TEXT)");try{d.execSQL("ALTER TABLE journal_entries ADD COLUMN description TEXT");}catch(Exception ignored){}d.execSQL("CREATE TABLE IF NOT EXISTS party_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,party_type TEXT NOT NULL,party_id INTEGER NOT NULL,direction TEXT NOT NULL,amount REAL NOT NULL,note TEXT,created_at INTEGER NOT NULL,journal_entry_id INTEGER NOT NULL)");d.execSQL("CREATE INDEX IF NOT EXISTS idx_party_payments_party_date ON party_payments(party_type,party_id,created_at)");
 d.execSQL("CREATE TABLE IF NOT EXISTS journal_lines(id INTEGER PRIMARY KEY AUTOINCREMENT,journal_entry_id INTEGER,account_id INTEGER,debit REAL NOT NULL DEFAULT 0,credit REAL NOT NULL DEFAULT 0)");
 String[][] ac={{"1010","الصندوق","ASSET"},{"1020","الحسابات البنكية","ASSET"},{"1100","العملاء","ASSET"},{"1200","المخزون","ASSET"},{"1300","سلف الموظفين","ASSET"},{"2100","الموردون","LIABILITY"},{"3000","رأس المال","EQUITY"},{"3100","الأرصدة الافتتاحية","EQUITY"},{"4000","المبيعات","REVENUE"},{"4100","مردودات المبيعات","CONTRA_REVENUE"},{"5100","تكلفة البضاعة المباعة","COST"},{"6000","المصروفات","EXPENSE"},{"2200","رواتب مستحقة","LIABILITY"},{"2300","استقطاعات رواتب مستحقة","LIABILITY"},{"6100","مصروف الرواتب","EXPENSE"}};for(String[] a:ac){ContentValues v=new ContentValues();v.put("code",a[0]);v.put("name",a[1]);v.put("type",a[2]);d.insertWithOnConflict("accounts",null,v,SQLiteDatabase.CONFLICT_IGNORE);}d.execSQL("CREATE INDEX IF NOT EXISTS idx_journal_lines_account ON journal_lines(account_id)");d.execSQL("CREATE INDEX IF NOT EXISTS idx_transactions_type ON transactions(type)");d.execSQL("CREATE INDEX IF NOT EXISTS idx_invoice_items_tx ON invoice_items(transaction_id)");}void exec(String s,Object...a){tx(s,a);}void tx(String s,Object...a){SQLiteDatabase d=getWritableDatabase();SQLiteStatement q=d.compileStatement(s);for(int i=0;i<a.length;i++){Object v=a[i];if(v==null)q.bindNull(i+1);else if(v instanceof Number)q.bindDouble(i+1,((Number)v).doubleValue());else q.bindString(i+1,String.valueOf(v));}q.execute();}Cursor q(String s,String...a){return getReadableDatabase().rawQuery(s,a);}}
